command:
// Roll an obedience check for the selected hireling.
const api = game.modules.get("acks-extras")?.api?.henchmen ?? globalThis.acksExtras?.henchmen;
if (!api) return ui.notifications.error("ACKS Extras is not active.");
if (typeof api.openObedienceRoll !== "function") return ui.notifications.warn("ACKS Extras | Obedience Check needs a newer build of this module.");
const actor = canvas.tokens.controlled[0]?.actor ?? game.user.character;
if (!actor) return ui.notifications.warn("Select a hireling token first.");
api.openObedienceRoll(actor);
